import{_ as t,l,o as e,c as n,v as o,p as s,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"浸没头与水膜","description":"","frontmatter":{"title":"浸没头与水膜","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/immersion-hood.md","filePath":"litho/immersion-hood.md","lastUpdated":1789023840000}'),m={name:"litho/immersion-hood.md"};function c(E,a,A,_,B,u){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="浸没头与水膜" tabindex="-1">浸没头与水膜 <a class="header-anchor" href="#浸没头与水膜" aria-label="Permalink to &quot;浸没头与水膜&quot;">​</a></h1><div class="epigraph"><p>浸没不是晶圆浸在水槽里扫描。局部喷淋头在最后一片镜头与晶圆之间维持一层随动的超纯水膜，弯月面稳，成像才稳。</p><footer>—— 据 ASML 对局部浸没 / immersion hood 的公开架构说明整理</footer></div><p><a href="/litho/arf-immersion">上一课</a>把介质替换写成 \\(\\mathrm{NA}=1.35\\)：加水是为了能设计更高孔径的物镜，不是给干式镜头乘 1.44。缺口是流体如何跟着扫描走。本课钉浸没头（immersion hood）与水膜。气泡、水印如何在弯月面失稳时写成缺陷，留给<a href="/litho/immersion-defects">下一课</a>；PAG 浸出另课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>物方间隙只有毫米量级的水，晶圆台却要以产线加速度步进–扫描。整片浸在水槽里会把惯性、污染和干燥变成不可控。量产答案是局部液浸：喷淋与回收做在镜头周围的头里，只在投影狭缝附近维持弯月面，晶圆其余部分是干的。ASML 公开故事把这套头与回收写成浸没机架构的一部分，而不是光学附件。</p><p>缺口因此是弯月面的力学与供水卫生，不是再推一次瑞利式。水膜厚度、温度和气泡决定有效焦面与局部 \\(n\\)，已经是成像参数。</p><h3 id="灌稳不等于光学已经结束" tabindex="-1">灌稳不等于光学已经结束 <a class="header-anchor" href="#灌稳不等于光学已经结束" aria-label="Permalink to &quot;灌稳不等于光学已经结束&quot;">​</a></h3><p>头把水留住，镜头镀膜才不被干湿循环打坏，晶圆才不会带走一层水去下一口。若回收跟不上扫描速度，弯月面破裂，光学可能还来得及报错，缺陷已经写下。浸没头的工艺窗口是速度–加速度–表面浸润的流体窗，与 E–D 窗正交。</p><p><span class="marginnote">水温改 193 nm 的折射率，因而改焦面。浸没机把水温当成像参数控，不是把水当普通冷却液。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>头的功能块公开可说的有：供水、排气/除泡、回收、与晶圆表面形成受控接触角的几何约束。扫描时水随狭缝移动；步进到下一场时弯月面要不断开或不留下液滴。晶圆边缘和切口是几何奇点，头必须在边场改流量或改路径——边 CDU 与边缺陷往往从这里来，不是镜头四角像差单独造成。</p><p>表面：胶与面涂的亲疏水决定接触角。头的设计假定一个浸润窗口；换胶等于换流体边界条件，扫描速度上限可能动。本课不给未公开的流速表，只要求：速度规格带胶种与头世代绑定。</p><h3 id="与双工件台的接口" tabindex="-1">与双工件台的接口 <a class="header-anchor" href="#与双工件台的接口" aria-label="Permalink to &quot;与双工件台的接口&quot;">​</a></h3><p>测量台是干的或另有策略，曝光台在水下。交接时水不能污染编码器与调平传感器。双台买的是产能，浸没头买的是在该产能下液膜仍闭合。两套架构叠在同一台 NXT 上，故障要分清是台还是头。</p>',14)),(e(),s(h,null,{default:i(()=>[p(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUP%5B%22%E8%B6%85%E7%BA%AF%E6%B0%B4%E4%BE%9B%E7%BB%99%22%5D%20--%3E%20HOOD%5B%22%E6%B5%B8%E6%B2%A1%E5%A4%B4%22%5D%0A%20%20HOOD%20--%3E%20FILM%5B%22%E5%B1%80%E9%83%A8%E6%B0%B4%E8%86%9C%20%2F%20%E5%BC%AF%E6%9C%88%E9%9D%A2%22%5D%0A%20%20REC%5B%22%E5%9B%9E%E6%94%B6%22%5D%20--%3E%20HOOD%0A%20%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E5%8A%A0%E9%80%9F%E5%BA%A6%22%5D%20--%3E%20FILM%0A%20%20FILM%20--%3E%20IMG%5B%22NA%201.35%20%E6%88%90%E5%83%8F%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>弯月面由表面张力、黏滞力和头内压差共同约束。加速度大时惯性把三相线拉断，吸入空气或甩出液滴。吸入的气体成为下一课的气泡；甩出的液滴在干燥后成为水印。光学上，稳定水膜等效于设计的物方 \\(n\\)；膜厚抖动是额外的焦噪声，会吃掉已经很薄的 DOF。</p><p>温度：供水若与晶圆、镜头不平衡，局部 \\(n\\) 梯度等于液体透镜，场内 CD 与套刻瞬态一起漂。公开论述把热控写成浸没 overlay 的贡献项之一，本课只把它接到头的供水，不重写编码器。</p><p><span class="marginnote">高折射率液体从未成为量产主流。头的流体设计是为水、为 \\(n\\approx 1.44\\) 冻结的。换液体不是拧一下流量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供 ASML 未公布的流量、间隙或扫描速度上限，也不把第一代 AT:1150i 的头与当代 NXT 画成同一张零件图。干式机没有这套流体窗。后课默认：说到浸没扫描，就是局部头维持的随动水膜；缺陷机制从弯月面失稳讲起，而不是从 NA 数字讲起。</p><p>颗粒可以从供水、回收和晶圆表面进入弯月面，表观上像光学颗粒缺陷。卫生属于轨道与水系统，修 OPC 无效。</p><p><span class="marginnote">边场扫描路径改流体条件，边缺陷与边 overlay 会同时变。诊断时先问是不是刚换了边缘策略，再问镜头。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>量产浸没是局部浸没头维持的随动水膜，不是水槽。</li><li>弯月面的流体窗与 E–D 窗正交，绑定扫描加速度和表面浸润。</li><li>水温与膜厚抖动进焦面，是成像参数。</li><li>边场和切口是流体奇点，常先于场心失败。</li><li>气泡与水印下一课。</li><li>出处：ASML 浸没架构与 TWINSCAN 公开故事；Mack 对浸没物镜的讨论。</li></ul>',10))])}const T=t(m,[["render",c]]);export{D as __pageData,T as default};
